export type PaginatedHistory = { entries: HistoryEntry[]; has_more: boolean }
export type PasteMethod = "ctrl_v" | "direct" | "none" | "shift_insert" | "ctrl_shift_v" | "external_script"
export type PeriodSummary = { avg_wpm: number; avg_filler_rate: number; session_count: number; prev_avg_wpm: number; prev_avg_filler_rate: number; prev_session_count: number }
export type PermissionAccess = "allowed" | "denied" | "unknown"
export type PostProcessProvider = { id: string; label: string; base_url: string; allow_base_url_edit?: boolean; models_endpoint?: string | null; supports_structured_output?: boolean }
/**
 * What the UI layer needs to know to show a question. Also returned by the
 * `agent_bridge_current` command so a freshly created panel window can pull
 * the active question on mount (the `agent-question` event may fire before
 * the webview is ready to listen — cold-window race).
 */
export type QuestionEvent = { id: number; kind: string; question: string; options: string[]; timeout_s: number; speak: boolean; source: string }
export type QuestionRow = { id: number; source: string; kind: string; question: string; options: string | null; answer: string | null; status: string; asked_at: number; answered_at: number | null }
/**
 * Compute device for the Qwen3-ASR sidecar. `Auto` picks CUDA when an NVIDIA
 * GPU with a working driver is present, otherwise CPU.
 */
export type QwenDeviceSetting = "auto" | "cuda" | "cpu"
export type QwenRuntimeStatus = { installed: boolean; version: string | null; installing: boolean; downloaded_bytes: number; total_bytes: number }
export type RecordingRetentionPeriod = "never" | "preserve_limit" | "days_3" | "weeks_2" | "months_3"
export type ScoreReport = { overall: number; words: WordScore[]; reference_word_count: number; matched_word_count: number; note: string }
export type SecretMap = Partial<{ [key in string]: string }>
export type ShortcutBinding = { id: string; name: string; description: string; default_binding: string; current_binding: string }
/**
 * A spoken-trigger text expansion: saying `trigger` inserts `text`.
 */
export type Snippet = { trigger: string; text: string }
export type SoundTheme = "marimba" | "pop" | "custom"
/**
 * Live-subtitle text size. The actual CSS pixel mapping is applied in the
 * overlay frontend (`SUBTITLE_FONT_PX`), keyed off this enum's serialized name.
 */
export type SubtitleFontSize = "small" | "medium" | "large"
export type TrendPoint = { day: number; avg_wpm: number; avg_filler_rate: number }
export type TrendWindow = "Days7" | "Days30" | "All"
export type TypingTool = "auto" | "wtype" | "kwtype" | "dotool" | "ydotool" | "xdotool"
export type VoiceInfo = { id: string; display_name: string; language: string }
export type WhisperAcceleratorSetting = "auto" | "cpu" | "gpu"
export type WindowsMicrophonePermissionStatus = { supported: boolean; overall_access: PermissionAccess; device_access: PermissionAccess; app_access: PermissionAccess; desktop_app_access: PermissionAccess }
export type WordScore = { reference: string; spoken: string | null; matched: boolean }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
